import React from "react";
import { Link, useParams } from "react-router-dom";

class Post extends React.Component {
    constructor(props){
        super(props);
        
         let {id} = useParams();
         console.log(id);
         
            this.state = {
                post: [],
                loading: true,
                base_URL: '',
                like_qty: 0,
                all_comment: 0,
                id: id
            };
        }
    
    
        componentDidMount() {
            console.log("Home Mounted");
    
            fetch("http://localhost:8000/api/post/" + this.state.id)
                .then(res => res.json())
                .then(json => {
                    this.setState({
                        loading: false,
                        post: json.post,
                        like_qty: json.like_qty,
                        all_comment: json.all_comment,
                        base_URL: json.base_URL
                    });
                })
                .catch(err => {
                    console.log("ERR:", err);
                    this.setState({ loading: false });
                });
        }
    render() {
        return (
            <>
            <main className="container mt-4 pt-5">
                <div className="container-fluid mt-5">
                    <div className="card mb-4 shadow-sm item-back text-color overflow-hidden rounded-4 boder">
                        <img src="img/aaa.png" alt="Post Image" className="post-img rounded-top-4"/>
                        <div className="card-body">
                            <h3 className="card-title">title</h3>
                            <p>12:12</p>
                            <p className="card-text">kbjabefuybwalfbawjlfbwyjbfjkwebfyuweb</p>
                            <div className="d-flex align-items-center mb-3">
                                <img src="img/aaa.png" alt="User" className="user-img me-3 rounded-circle boder"/>
                                <div>
                                    <Link to={"/profile"} className="text-decoration-none text-color px-2 pt-1 pb-1 mb-2 rounded-3">
                                        name
                                    </Link>
                                </div>
                            </div>
                            <div className="d-flex align-items-center gap-2 mb-3">
                                <span onclick="like({{ $post->id }})" id="span_like">
                                        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="red" viewBox="0 0 24 24">
                                            <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 
                                                                    4.42 3 7.5 3c1.74 0 3.41 0.81 4.5 2.09C13.09 3.81 
                                                                    14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 
                                                                    6.86-8.55 11.54L12 21.35z" />
                                        </svg>
                                </span>
                                <span id="count_like">666</span>
                            </div>
                            <form method="post">
                                <input type="text" className="d-none" name="post_id" value="{{ $post->id }}" id="post_id_form"/>
                                <div className="mb-3">
                                    <textarea className="form-control" name="text" rows="2" placeholder="Write a comment..."
                                        id="text_form"></textarea>
                                </div>
                                <span onclick="comment()" className="btn btn-theme boder">Send Comment</span>
                            </form>
                        </div>
                    </div>
                    <div className="shadow-sm item-back p-4 mb-3 boder rounded-4">
                        <h5 className="mb-4">Comments <span id="count_comment">(123)</span></h5>
                        <div id="all_comment">
                            <div className="d-flex mb-3">
                                <img src="img/aaa.png" alt="User" className="user-img me-3 rounded-circle boder"/>
                                <div>
                                    <Link to={"/profile"} className="text-decoration-none text-color px-2 pt-1 pb-1 mb-2 rounded-3">
                                        name
                                    </Link>

                                    <p className="mb-0">text sudfyusbfuyebyc</p>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </main>
            </>
        );
    }
}
export default Post;
